#!/usr/bin/env bash
# Wrapper around `zig cc` used as the host C compiler/linker in this sandbox.
# Normalises Rust/cc-rs conventions that zig's driver does not accept:
#   * GNU-only linker flag --fix-cortex-a53-843419 (rejected by zig's LLD)
