        --target=aarch64-unknown-linux-gnu) args+=("--target=aarch64-linux-gnu") ;;
        --target=x86_64-unknown-linux-gnu) args+=("--target=x86_64-linux-gnu") ;;
        *) args+=("$arg") ;;
    esac
done
exec "$HOME/.local/zig/zig" cc "${args[@]}"

